{"witnessCode": "import { describe, it } from 'node:test';
import { strict as assert } from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('hasCustomProtocol dot regression', () => {
  it('should treat a URL with a dot in the scheme as non-custom (throw on invalid URL)', () => {
    const input = 'foo.bar:baz';
    assert.throws(() => {
      normalizeUrl(input, {});
    }, Error);
  });
});"}
